// Package dbconv converts sqlc row types into domain (store) types.
//
// The mapping is generated by goverter into gen/ from the Converter
// interface; this file holds only the interface and the value rules it
// calls through `extend`. Writes stay hand-written in package sqlite, since
// their parameter structs carry values (ids, "now") that are not copies.
package dbconv

//go:generate rm -rf gen
//go:generate go run github.com/jmattheis/goverter/cmd/goverter@v1.11.1 gen .

import (
	"time"

	"github.com/jacobalberty/beenfar/internal/store"
	"github.com/jacobalberty/beenfar/internal/store/sqlite/gen/db"
)

// Converter is implemented by gen/ (package dbconvgen) as plain functions.
//
// goverter:converter
// goverter:output:file ./gen/dbconv.go
// goverter:output:package github.com/jacobalberty/beenfar/internal/store/sqlite/dbconv/gen:dbconvgen
// goverter:output:format function
// goverter:matchIgnoreCase
// goverter:extend FromMilli Int
// goverter:extend DeviceState Readoption WifiSecurity WifiBand UserSource
type Converter interface {
	Device(db.Device) store.Device
	Devices([]db.Device) []store.Device

	// APGroups live in their own table; the caller fills them in.
	// goverter:ignore APGroups
	WifiNetwork(db.WifiNetwork) store.WifiNetwork

	Network(db.Network) store.Network
	Networks([]db.Network) []store.Network

	User(db.User) store.User
	Users([]db.User) []store.User

	// goverter:map ExpireTime ExpireTime | FromOptMilli
	// goverter:map LastUsedTime LastUsedTime | FromOptMilli
	APIToken(db.ApiToken) store.APIToken
	APITokens([]db.ApiToken) []store.APIToken

	// goverter:map LastUsedTime LastUsedTime | FromOptMilli
	AdapterToken(db.AdapterToken) store.AdapterToken

	Session(db.Session) store.Session
}

// FromMilli converts unix milliseconds to UTC time.
func FromMilli(ms int64) time.Time { return time.UnixMilli(ms).UTC() }

// FromOptMilli is FromMilli, with 0 meaning unset (the zero time).
func FromOptMilli(ms int64) time.Time {
	if ms == 0 {
		return time.Time{}
	}
	return FromMilli(ms)
}

// Int narrows an INTEGER column whose range is enforced by a CHECK.
func Int(v int64) int { return int(v) }

// The enum columns are constrained by CHECKs to the domain values.

func DeviceState(s string) store.DeviceState   { return store.DeviceState(s) }
func Readoption(s string) store.Readoption     { return store.Readoption(s) }
func WifiSecurity(s string) store.WifiSecurity { return store.WifiSecurity(s) }
func WifiBand(s string) store.WifiBand         { return store.WifiBand(s) }
func UserSource(s string) store.UserSource     { return store.UserSource(s) }
